package fts_test

// Writer conformance harness (UCL rule U4): replays committed scenario JSONs
// on frigolite and compares the resulting FTS shadow-table state against the
// oracle fixture databases generated by tools/orafixture. Failures report the
// FIRST divergence — table, blockid, height, byte offset and decoded context
// — instead of a scalar mismatch.

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"testing"

	frigolite "github.com/pijalu/frigolite"
	fts "github.com/pijalu/frigolite/internal/fts"
)

const scenarioDir = "testdata/ftsconformance"

// scenario mirrors tools/orafixture's input format.
type scenario struct {
	Name     string            `json:"name"`
	Pragmas  map[string]string `json:"pragmas"`
	SQLFiles []string          `json:"sqlFiles"`
	SQL      []string          `json:"sql"`
}

type segdirRow struct {
	level, idx     int64
	startBlock     int64
	leavesEndBlock int64
	endBlock       int64
}

func TestWriterConformance(t *testing.T) {
	files, err := filepath.Glob(filepath.Join(scenarioDir, "*.json"))
	if err != nil {
		t.Fatal(err)
	}
	if len(files) == 0 {
		t.Fatalf("no scenarios found in %s", scenarioDir)
	}
	sort.Strings(files)
	for _, f := range files {
		sc := readScenario(t, f)
		t.Run(sc.Name, func(t *testing.T) { runConformanceScenario(t, f, sc) })
	}
}

func readScenario(t *testing.T, path string) *scenario {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var sc scenario
	if err := json.Unmarshal(data, &sc); err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	return &sc
}

// runConformanceScenario replays one scenario on a fresh frigolite database
// and diffs the FTS state against the oracle fixture <name>.db.
func runConformanceScenario(t *testing.T, path string, sc *scenario) {
	t.Helper()
	dir := t.TempDir()
	replayPath := filepath.Join(dir, "replay.db")

	db, err := frigolite.Open(replayPath)
	if err != nil {
		t.Fatalf("open replay db: %v", err)
	}
	execScript := func(sql string) error {
		if r := db.Exec(sql); r.Error != nil {
			return fmt.Errorf("exec %q: %v", truncate(sql, 80), r.Error)
		}
		return nil
	}
	keys := make([]string, 0, len(sc.Pragmas))
	for k := range sc.Pragmas {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		if err := execScript(fmt.Sprintf("PRAGMA %s=%s;", k, sc.Pragmas[k])); err != nil {
			t.Fatal(err)
		}
	}
	for _, sf := range sc.SQLFiles {
		data, err := os.ReadFile(filepath.Join(filepath.Dir(path), sf))
		if err != nil {
			t.Fatal(err)
		}
		if err := execScript(string(data)); err != nil {
			t.Fatal(err)
		}
	}
	for _, s := range sc.SQL {
		if err := execScript(s + ";"); err != nil {
			t.Fatal(err)
		}
	}
	tables := ftsTables(t, db)
	if err := db.Close(); err != nil {
		t.Fatalf("close replay db: %v", err)
	}

	oraclePath := filepath.Join(filepath.Dir(path), sc.Name+".db")
	if _, err := os.Stat(oraclePath); err != nil {
		t.Fatalf("oracle fixture missing for scenario %s: %v", sc.Name, err)
	}

	for _, table := range tables {
		compareTable(t, replayPath, oraclePath, table)
	}
}

// ftsTables lists FTS virtual tables present in the replayed database.
func ftsTables(t *testing.T, db *frigolite.DB) []string {
	t.Helper()
	r := db.Query("SELECT name FROM sqlite_master WHERE type='table' AND sql LIKE 'CREATE VIRTUAL TABLE%' ORDER BY name")
	if r.Error != nil {
		t.Fatal(r.Error)
	}
	var names []string
	for _, row := range r.Rows {
		names = append(names, row[0].(string))
	}
	return names
}

func queryIntRows(t *testing.T, db *frigolite.DB, query string) [][5]int64 {
	t.Helper()
	r := db.Query(query)
	if r.Error != nil {
		t.Fatal(r.Error)
	}
	rows := make([][5]int64, 0, len(r.Rows))
	for _, row := range r.Rows {
		var out [5]int64
		for i := 0; i < 5; i++ {
			out[i] = toInt(row[i])
		}
		// %_segdir.end_block is an INTEGER blockid, or — when the writer knows
		// the segment size — a BLOB holding the varint PAIR (blockid, size)
		// (fts3_write.c fts3WriteSegdir). Compare on the decoded blockid.
		out[4] = decodeEndBlock(row[4])
		rows = append(rows, out)
	}
	return rows
}

// toInt converts an SQL integer cell (frigolite may deliver several Go
// numeric types) to int64; nil becomes 0.
func toInt(v interface{}) int64 {
	switch n := v.(type) {
	case int64:
		return n
	case uint64:
		return int64(n)
	case int:
		return int64(n)
	case float64:
		return int64(n)
	default:
		return 0
	}
}

// decodeEndBlock normalizes a %_segdir.end_block cell to its blockid.
// Depending on storage and driver surface it appears as an integer cell, a
// raw two-varint blob, or the decimal text form of that pair.
func decodeEndBlock(v interface{}) int64 {
	switch t := v.(type) {
	case []byte:
		id, _ := fts.GetFTS3Varint(t)
		return int64(id)
	case string:
		n, err := strconv.ParseInt(strings.TrimSpace(t), 10, 64)
		if err == nil {
			return n
		}
		fields := strings.Fields(t)
		if len(fields) > 0 {
			n, _ := strconv.ParseInt(fields[0], 10, 64)
			return n
		}
		return 0
	default:
		return toInt(v)
	}
}

func compareTable(t *testing.T, replayPath, oraclePath, table string) {
	t.Helper()
	replay, err := frigolite.Open(replayPath)
	if err != nil {
		t.Fatal(err)
	}
	defer replay.Close()
	oracle, err := frigolite.Open(oraclePath)
	if err != nil {
		t.Fatal(err)
	}
	defer oracle.Close()

	t.Run("segdir:"+table, func(t *testing.T) {
		q := fmt.Sprintf("SELECT level, idx, start_block, leaves_end_block, end_block FROM %s_segdir ORDER BY level DESC, idx", table)
		got := queryIntRows(t, replay, q)
		want := queryIntRows(t, oracle, q)
		for i := 0; i < len(got) || i < len(want); i++ {
			if i >= len(got) || i >= len(want) || got[i] != want[i] {
				t.Fatalf("first segdir divergence at row %d:\n  got:  %+v\n  want: %+v\n  full got:  %v\n  full want: %v",
					i+1, rowOr(got, i), rowOr(want, i), got, want)
			}
		}
	})

	t.Run("root:"+table, func(t *testing.T) {
		q := fmt.Sprintf("SELECT idx, root FROM %s_segdir ORDER BY level DESC, idx", table)
		gotRoots := loadRoots(t, replay, q)
		wantRoots := loadRoots(t, oracle, q)
		for i := 0; i < len(gotRoots) || i < len(wantRoots); i++ {
			var gi, wi int64
			var gb, wb []byte
			if i < len(gotRoots) {
				gi, gb = gotRoots[i].idx, gotRoots[i].root
			}
			if i < len(wantRoots) {
				wi, wb = wantRoots[i].idx, wantRoots[i].root
			}
			if gi != wi || !bytesEqual(gb, wb) {
				off := firstDiffOffset(gb, wb)
				t.Fatalf("first root divergence at row %d (idx got=%d want=%d):\n  got:  %d bytes, first diff at offset %v\n  want: %d bytes",
					i+1, gi, wi, len(gb), off, len(wb))
			}
		}
	})

	t.Run("segments:"+table, func(t *testing.T) {
		gotBlocks := loadBlocks(t, replay, table)
		wantBlocks := loadBlocks(t, oracle, table)

		// Per-block length table summary on failure.
		report := func() string {
			var b strings.Builder
			ids := blockIDs(gotBlocks, wantBlocks)
			fmt.Fprintf(&b, "block length table (got=%d blocks, want=%d blocks):\n", len(gotBlocks), len(wantBlocks))
			for _, id := range ids {
				fmt.Fprintf(&b, "  %6d  got=%6d  want=%6d\n", id, len(gotBlocks[id]), len(wantBlocks[id]))
			}
			return b.String()
		}
		firstID, diverged := firstDivergentBlock(gotBlocks, wantBlocks)
		if !diverged {
			return
		}
		msg := fmt.Sprintf("first segment divergence at blockid %d\n%s%s",
			firstID, report(), decodeDivergence(firstID, gotBlocks[firstID], wantBlocks[firstID]))
		t.Fatal(msg)
	})
}

// rootRow is one %_segdir root blob keyed by idx.
type rootRow struct {
	idx  int64
	root []byte
}

func loadRoots(t *testing.T, db *frigolite.DB, q string) []rootRow {
	t.Helper()
	r := db.Query(q)
	if r.Error != nil {
		t.Fatal(r.Error)
	}
	var out []rootRow
	for _, row := range r.Rows {
		rr := rootRow{idx: toInt(row[0])}
		switch v := row[1].(type) {
		case []byte:
			rr.root = v
		case string:
			rr.root = []byte(v)
		}
		out = append(out, rr)
	}
	return out
}

func firstDiffOffset(a, b []byte) interface{} {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i] != b[i] {
			return i
		}
	}
	if len(a) != len(b) {
		return n
	}
	return nil
}

func rowOr(rows [][5]int64, i int) *[5]int64 {
	if i < len(rows) {
		return &rows[i]
	}
	return nil
}

func loadBlocks(t *testing.T, db *frigolite.DB, table string) map[int64][]byte {
	t.Helper()
	r := db.Query(fmt.Sprintf("SELECT blockid, block FROM %s_segments WHERE block IS NOT NULL ORDER BY blockid", table))
	if r.Error != nil {
		t.Fatal(r.Error)
	}
	blocks := map[int64][]byte{}
	for _, row := range r.Rows {
		id := row[0].(int64)
		switch v := row[1].(type) {
		case []byte:
			blocks[id] = v
		case string:
			blocks[id] = []byte(v)
		default:
			t.Fatalf("block %d: unexpected type %T", id, row[1])
		}
	}
	return blocks
}

func blockIDs(a, b map[int64][]byte) []int64 {
	set := map[int64]bool{}
	for id := range a {
		set[id] = true
	}
	for id := range b {
		set[id] = true
	}
	ids := make([]int64, 0, len(set))
	for id := range set {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
	return ids
}

func firstDivergentBlock(got, want map[int64][]byte) (int64, bool) {
	for _, id := range blockIDs(got, want) {
		gb, hasGot := got[id]
		wb, hasWant := want[id]
		if !hasGot || !hasWant || !bytesEqual(gb, wb) {
			return id, true
		}
	}
	return 0, false
}

func bytesEqual(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// decodeDivergence decodes both versions of a diverged block with the segview
// decoders and names the first differing byte plus its decoded context.
func decodeDivergence(id int64, gotBlob, wantBlob []byte) string {
	var b strings.Builder
	fmt.Fprintf(&b, "block %d: got %d bytes, want %d bytes\n", id, len(gotBlob), len(wantBlob))
	n := len(gotBlob)
	if len(wantBlob) < n {
		n = len(wantBlob)
	}
	for i := 0; i < n; i++ {
		if gotBlob[i] != wantBlob[i] {
			fmt.Fprintf(&b, "  first differing byte at offset %d: got 0x%02x want 0x%02x\n", i, gotBlob[i], wantBlob[i])
			break
		}
	}
	for label, blob := range map[string][]byte{"got": gotBlob, "want": wantBlob} {
		node, err := fts.DecodeSegmentBlock(blob)
		if err != nil {
			fmt.Fprintf(&b, "  %s: undecodable: %v\n", label, err)
			continue
		}
		fmt.Fprintf(&b, "  %s: height=%d left-child=%d entries=%d", label, node.Height, node.LeftChild, len(node.Entries))
		if node.Height > 0 && len(node.Entries) > 0 {
			fmt.Fprintf(&b, " first-sep=%q last-sep=%q", node.Entries[0].Term, node.Entries[len(node.Entries)-1].Term)
		} else if node.Height == 0 && len(node.Entries) > 0 {
			fmt.Fprintf(&b, " first-term=%q last-term=%q", node.Entries[0].Term, node.Entries[len(node.Entries)-1].Term)
		}
		b.WriteString("\n")
	}
	return b.String()
}

func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "..."
}
